# We generate a nontrivial rectangular board with both dimensions at least 6,
# and occasionally make them unequal to ensure generality and hardness.
# Uses rng.* only.
for _ in range(100):
    r = rng.randint(6, 35)
    c = rng.randint(6, 35)
    # Avoid too trivial square small boards, ensure diversity
    if r * c >= 200 and (r != c or rng.random() < 0.5):
        return {'rows': r, 'cols': c}
# Fallback in rare cases
return {'rows': 19, 'cols': 31}

    def verifier(assign):
# Validate domains and compute the guaranteed maximum black count.
# The operation space is the cut-space of K_{rows,cols}: reachable configurations
# are obtained by adding (mod 2) a matrix of the form u_i \oplus v_j to the initial board.
# The largest guaranteed number of black stones is rows*cols - min(rows, cols) + 1.
try:
    r = int(assign.get('rows', None))
    c = int(assign.get('cols', None))
except Exception:
    # Invalid types
    return (False, None)
# Domain checks to enforce non-triviality
if r is None or c is None:
    return (False, None)
if r < 6 or c < 6:
    # Enforce hardness: tiny boards are too easy
    return (False, None)
# Compute answer
answer = r * c - min(r, c) + 1
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

